import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.slayer.SlayerPlugin;
import net.runelite.client.plugins.slayer.SlayerPluginService;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Slayer Task ETA",
	description = "Shows how long until your current Slayer task is finished, based on your kill rate",
	tags = {"slayer", "eta", "kills", "kph", "timer", "task"}
)
@PluginDependency(SlayerPlugin.class)
public class SlayerEtaPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(SlayerEtaPlugin.class);

	private static final String RATE_KEY_PREFIX = "kph_";
	private static final String BREAKS_KEY_PREFIX = "breaks_";
	private static final int SAVE_EVERY_KILLS = 10;

	/** After the superior message, the next task kill is treated as the superior for this long. */
	private static final long SUPERIOR_WINDOW_MS = 10 * 60_000L;

	private static final String SUPERIOR_MESSAGE = "A superior foe has appeared...";
	// Checking the task with an enchanted gem, Slayer helmet or Slayer ring. The
	// menu click below is the main way this is noticed; the chat message is a backup.
	private static final String TASK_CHECK_MESSAGE = "You're assigned to kill";
	private static final String CHECK_OPTION = "Check";

	@Inject
	private SlayerPluginService slayerService;

	@Inject
	private SlayerEtaConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SlayerEtaOverlay overlay;

	@Inject
	private Notifier notifier;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Client client;

	private final KillRateTracker tracker = new KillRateTracker();
	private final TimeOnTask timeOnTask = new TimeOnTask();

	private String currentTask;
	private int remaining;
	private int lastRemaining = -1;

	/** Kills/hr remembered from a previous session for the current task, or 0. */
	private double savedKph;

	/**
	 * Break estimate from before this session's kills (see {@link KillRateTracker#breakRatio}),
	 * or -1 for none. Set when a task starts and not changed by saving, so this
	 * session's numbers are never counted twice.
	 */
	private double priorBreakRatio = -1;

	private boolean visible;
	private long lastShowMs;

	private int killsAtLastSave;
	private boolean notified;

	/** Set on logout; the first tick after logging back in takes the task count as it finds it. */
	private boolean resync;

	/** When the superior message was seen, or -1. */
	private long superiorSinceMs = -1;

	@Provides
	SlayerEtaConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerEtaConfig.class);
	}

	@Override
	protected void startUp()
	{
		clearTask();
		overlay.rebuildMenu();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		saveRate();
		overlayManager.remove(overlay);
		clearTask();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SlayerEtaConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		// Saving a rate also reports a change in this group; only real settings matter here.
		String key = event.getKey();
		if (key != null && (key.startsWith(RATE_KEY_PREFIX) || key.startsWith(BREAKS_KEY_PREFIX)))
		{
			return;
		}

		// Settings change on the UI thread; the overlay is drawn on the client thread.
		clientThread.invokeLater(overlay::rebuildMenu);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state != GameState.LOGIN_SCREEN && state != GameState.CONNECTION_LOST)
		{
			return;
		}

		// Logged out or dropped. Stop the time-on-task clock, and make sure the
		// time spent away is never counted as a pause or a break.
		timeOnTask.pause(clock());
		tracker.clearClock();
		superiorSinceMs = -1;
		resync = true;

		if (state == GameState.LOGIN_SCREEN)
		{
			// Never show on login; it comes back on a task kill or a task check.
			visible = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		long now = clock();
		// Ticks only happen while logged in, so this carries on after a logout.
		timeOnTask.resume(now);

		String task = slayerService.getTask();
		int left = slayerService.getRemainingAmount();

		if (task == null || task.isEmpty() || left <= 0)
		{
			if (currentTask != null)
			{
				saveRate();
				clearTask();
			}
			return;
		}

		if (!task.equalsIgnoreCase(currentTask))
		{
			saveRate();
			startTask(task, left);
			return;
		}

		if (resync)
		{
			// First tick after a logout. The count may have changed while away (kills
			// made on mobile, say), and that isn't a kill we saw, so just take it as is.
			resync = false;
			lastRemaining = left;
			remaining = left;
			return;
		}

		if (left < lastRemaining)
		{
			int kills = lastRemaining - left;
			lastRemaining = left;
			remaining = left;
			onTaskKills(kills, now);
		}
		else if (left > lastRemaining)
		{
			// Task count went up (extended, or a fresh assignment of the same
			// monster). Keep the remembered rate but start timing again.
			saveRate();
			tracker.reset();
			timeOnTask.reset();
			killsAtLastSave = 0;
			notified = false;
			superiorSinceMs = -1;
			savedKph = loadRate(task);
			priorBreakRatio = loadBreakRatio(task);
		}

		lastRemaining = left;
		remaining = left;

		long hideDelayMs = EtaMath.hideDelayMs(config.hideAfterMinutes(), config.idleThreshold());
		if (visible && hideDelayMs > 0 && now - lastShowMs > hideDelayMs)
		{
			visible = false;
		}
	}

	private void onTaskKills(int kills, long now)
	{
		if (superiorPending(now))
		{
			// Leave the superior fight out of the rate, and don't count it as a break.
			tracker.restartClock(now);
			superiorSinceMs = -1;
		}
		else
		{
			tracker.recordKills(kills, now, config.idleThreshold() * 1000L);
		}

		timeOnTask.start(now);
		show(now);

		if (tracker.getCountedKills() - killsAtLastSave >= SAVE_EVERY_KILLS)
		{
			saveRate();
		}

		checkNotification();
	}

	private boolean superiorPending(long now)
	{
		return superiorSinceMs >= 0 && now - superiorSinceMs <= SUPERIOR_WINDOW_MS;
	}

	// ------------------------------------------------------------------ chat and task checks

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (message.contains(SUPERIOR_MESSAGE))
		{
			superiorSinceMs = clock();
		}
		else if (message.startsWith(TASK_CHECK_MESSAGE))
		{
			show(clock());
		}
	}

	/**
	 * Notice "Check" being clicked on an enchanted gem, Slayer helmet or Slayer
	 * ring, the same way RuneLite's own Slayer plugin does.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!CHECK_OPTION.equals(event.getMenuOption()))
		{
			return;
		}

		MenuAction action = event.getMenuAction();
		if (action != MenuAction.CC_OP && action != MenuAction.CC_OP_LOW_PRIORITY)
		{
			return;
		}

		Widget widget = client.getWidget(event.getParam1());
		if (widget != null && event.getParam0() != -1)
		{
			widget = widget.getChild(event.getParam0());
		}
		if (widget == null)
		{
			return;
		}

		int itemId = widget.getItemId();
		if (itemId == -1)
		{
			// Equipped items keep the item on a child of the slot instead.
			Widget[] children = widget.getDynamicChildren();
			if (children != null)
			{
				for (Widget child : children)
				{
					itemId = child.getItemId();
					if (itemId != -1)
					{
						break;
					}
				}
			}
		}

		// Every helmet colour and ring charge maps to the base helmet / ring here.
		itemId = ItemVariationMapping.map(itemId);
		if (itemId == ItemID.SLAYER_HELM || itemId == ItemID.SLAYER_RING_8
			|| itemId == ItemID.SLAYER_GEM || itemId == ItemID.SLAYER_ETERNAL_GEM)
		{
			show(clock());
		}
	}

	// ------------------------------------------------------------------ notification

	private void checkNotification()
	{
		if (notified || !config.notification().isEnabled() || currentTask == null)
		{
			return;
		}

		if (config.notifyTrigger() == NotifyTrigger.KILLS_LEFT)
		{
			if (remaining <= config.notifyKills())
			{
				notified = true;
				notifier.notify(config.notification(),
					"Slayer task: " + remaining + (remaining == 1 ? " kill left" : " kills left"));
			}
			return;
		}

		long secondsLeft = getEtaSeconds();
		if (secondsLeft >= 0 && secondsLeft <= config.notifyMinutes() * 60L)
		{
			notified = true;
			notifier.notify(config.notification(),
				"Slayer task: about " + EtaMath.formatEta(secondsLeft, EtaFormat.WORDS) + " left");
		}
	}

	// ------------------------------------------------------------------ values for the overlay

	String getCurrentTask()
	{
		return currentTask;
	}

	int getRemaining()
	{
		return remaining;
	}

	boolean isVisible()
	{
		return visible;
	}

	/**
	 * The rate the ETA should use: the live rate once there are enough kills
	 * this session, otherwise the remembered rate for this task.
	 */
	double getEffectiveKph()
	{
		if (hasLiveRate())
		{
			if (config.averageMode() == AverageMode.LAST_KILLS)
			{
				double rolling = tracker.getKillsPerHour(config.rollingKills());
				if (rolling > 0)
				{
					return rolling;
				}
			}
			return tracker.getKillsPerHour();
		}
		return config.rememberRates() ? savedKph : 0;
	}

	boolean hasLiveRate()
	{
		return tracker.getCountedKills() >= config.minKills() && tracker.getKillsPerHour() > 0;
	}

	int getKillsUntilLiveRate()
	{
		return Math.max(0, config.minKills() - tracker.getCountedKills());
	}

	/**
	 * Seconds until the task is finished, or -1 if there is no rate yet. Breaks
	 * are allowed for when that setting is on and there is an estimate to use.
	 */
	long getEtaSeconds()
	{
		double breakRatio = -1;
		if (config.includeBreaks())
		{
			breakRatio = tracker.getBreakRatio(config.rememberRates() ? priorBreakRatio : -1);
		}
		return EtaMath.etaSeconds(remaining, getEffectiveKph(), breakRatio);
	}

	/** Time since the first task kill, not counting time logged out, in ms, or -1. */
	long getTimeOnTaskMs()
	{
		return timeOnTask.getElapsedMs(clock());
	}

	// ------------------------------------------------------------------ right-click actions

	/** Restart this session's live rate and break estimate. Saved values and time on task are kept. */
	void resetSessionRate()
	{
		tracker.reset();
		killsAtLastSave = 0;
	}

	/** Forget the remembered rate and break estimate for the current task. */
	void clearSavedRate()
	{
		if (currentTask == null)
		{
			return;
		}
		configManager.unsetRSProfileConfiguration(SlayerEtaConfig.GROUP, rateKey(currentTask));
		configManager.unsetRSProfileConfiguration(SlayerEtaConfig.GROUP, breaksKey(currentTask));
		savedKph = 0;
		priorBreakRatio = -1;
		killsAtLastSave = tracker.getCountedKills();
	}

	// ------------------------------------------------------------------ task state

	/** The current time in ms. Its own method so a test can drive time by hand. */
	long clock()
	{
		return System.currentTimeMillis();
	}

	private void show(long now)
	{
		if (currentTask == null)
		{
			// Nothing to show yet (no task), and it mustn't pop up later when one is given.
			return;
		}
		visible = true;
		lastShowMs = now;
	}

	private void startTask(String task, int left)
	{
		currentTask = task;
		remaining = left;
		lastRemaining = left;
		tracker.reset();
		timeOnTask.reset();
		killsAtLastSave = 0;
		notified = false;
		resync = false;
		superiorSinceMs = -1;
		savedKph = loadRate(task);
		priorBreakRatio = loadBreakRatio(task);
		log.debug("Tracking task {} ({} left), saved rate {}, saved break ratio {}",
			task, left, savedKph, priorBreakRatio);
	}

	private void clearTask()
	{
		currentTask = null;
		remaining = 0;
		lastRemaining = -1;
		savedKph = 0;
		priorBreakRatio = -1;
		killsAtLastSave = 0;
		notified = false;
		resync = false;
		superiorSinceMs = -1;
		visible = false;
		tracker.reset();
		timeOnTask.reset();
	}

	private void saveRate()
	{
		if (!config.rememberRates() || currentTask == null || !hasLiveRate())
		{
			return;
		}

		// Always save the whole-task rate: it's the steadier number to start from next time.
		double kph = tracker.getKillsPerHour();
		configManager.setRSProfileConfiguration(SlayerEtaConfig.GROUP, rateKey(currentTask),
			String.format(Locale.ROOT, "%.1f", kph));
		savedKph = kph;

		double breakRatio = tracker.getBreakRatio(priorBreakRatio);
		if (breakRatio >= 0)
		{
			configManager.setRSProfileConfiguration(SlayerEtaConfig.GROUP, breaksKey(currentTask),
				String.format(Locale.ROOT, "%.3f", breakRatio));
		}
		killsAtLastSave = tracker.getCountedKills();
	}

	private double loadRate(String task)
	{
		double value = loadNumber(rateKey(task));
		return value > 0 ? value : 0;
	}

	private double loadBreakRatio(String task)
	{
		double value = loadNumber(breaksKey(task));
		return value >= 0 ? value : -1;
	}

	/** A saved number, or -1 if there isn't one (or it can't be read). */
	private double loadNumber(String key)
	{
		String value = configManager.getRSProfileConfiguration(SlayerEtaConfig.GROUP, key);
		if (value == null)
		{
			return -1;
		}
		try
		{
			double number = Double.parseDouble(value);
			return Double.isFinite(number) ? number : -1;
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private static String rateKey(String task)
	{
		return RATE_KEY_PREFIX + slug(task);
	}

	private static String breaksKey(String task)
	{
		return BREAKS_KEY_PREFIX + slug(task);
	}

	private static String slug(String task)
	{
		return task.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "_");
	}
}

package com.slayereta;

/**
 * Real time spent on the current task, counting only time spent logged in.
 *
 * It starts at the first task kill. Logging out pauses it and logging back in
 * carries on, so an idle logout or a disconnect doesn't wipe it.
 */
class TimeOnTask
{
	private boolean started;
	private long accumulatedMs;
	/** When the clock last started running, or -1 while paused. */
	private long runningSinceMs = -1;

	/** Start timing at {@code nowMs}. Does nothing if already started. */
	void start(long nowMs)
	{
		if (started)
		{
			return;
		}
		started = true;
		accumulatedMs = 0;
		runningSinceMs = nowMs;
	}

	/** Stop the clock, keeping what has been counted. Does nothing if not running. */
	void pause(long nowMs)
	{
		if (runningSinceMs < 0)
		{
			return;
		}
		accumulatedMs += Math.max(0, nowMs - runningSinceMs);
		runningSinceMs = -1;
	}

	/** Carry on after a pause. Does nothing if never started or already running. */
	void resume(long nowMs)
	{
		if (started && runningSinceMs < 0)
		{
			runningSinceMs = nowMs;
		}
	}

	/** Time on task so far in ms, or -1 if it hasn't started. */
	long getElapsedMs(long nowMs)
	{
		if (!started)
		{
			return -1;
		}
		long running = runningSinceMs >= 0 ? Math.max(0, nowMs - runningSinceMs) : 0;
		return accumulatedMs + running;
	}

	void reset()
	{
		started = false;
		accumulatedMs = 0;
		runningSinceMs = -1;
	}
}

package com.slayereta;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class EtaMathTest
{
	@Test
	public void noRateMeansNoEta()
	{
		assertEquals(-1, EtaMath.etaSeconds(100, 0, -1));
		assertEquals(-1, EtaMath.etaSeconds(100, -5, 0.5));
	}

	@Test
	public void etaWithoutBreaks()
	{
		// 60 kills at 120/hr is half an hour
		assertEquals(1800, EtaMath.etaSeconds(60, 120, -1));
		assertEquals(1800, EtaMath.etaSeconds(60, 120, 0));
	}

	@Test
	public void breaksStretchTheEta()
	{
		// 60 minutes of killing left with 5 minutes of breaks per 45 of killing
		assertEquals(Math.round(3600 * (1 + 5.0 / 45.0)), EtaMath.etaSeconds(120, 120, 5.0 / 45.0));
		// 0.25 means 15 minutes of breaks per hour of killing
		assertEquals(4500, EtaMath.etaSeconds(120, 120, 0.25));
	}

	@Test
	public void hideDelayIsTheLongerOfHideAfterAndPauseTime()
	{
		assertEquals(300_000, EtaMath.hideDelayMs(5, 120));
		assertEquals(120_000, EtaMath.hideDelayMs(1, 120));
		assertEquals(600_000, EtaMath.hideDelayMs(5, 600));
	}

	@Test
	public void hideAfterZeroMeansNever()
	{
		assertEquals(0, EtaMath.hideDelayMs(0, 120));
		assertEquals(0, EtaMath.hideDelayMs(0, 1800));
	}

	@Test
	public void etaFormatting()
	{
		assertEquals("45s", EtaMath.formatEta(45, EtaFormat.WORDS));
		assertEquals("12m 5s", EtaMath.formatEta(725, EtaFormat.WORDS));
		assertEquals("1h 23m", EtaMath.formatEta(4980, EtaFormat.WORDS));
		assertEquals("1:23:00", EtaMath.formatEta(4980, EtaFormat.DIGITAL));
		assertEquals("0:00:45", EtaMath.formatEta(45, EtaFormat.DIGITAL));
		assertEquals("0s", EtaMath.formatEta(0, EtaFormat.WORDS));
	}

	@Test
	public void clockFormatting()
	{
		java.time.LocalTime t = java.time.LocalTime.of(15, 7);
		assertEquals("15:07", t.format(ClockFormat.TWENTY_FOUR_HOUR.getFormatter()));
		assertEquals("3:07 PM", t.format(ClockFormat.TWELVE_HOUR.getFormatter()));
		assertEquals("12:00 AM", java.time.LocalTime.MIDNIGHT.format(ClockFormat.TWELVE_HOUR.getFormatter()));
	}
}

package com.slayereta;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class KillRateTrackerTest
{
	private static final long PAUSE_MS = 120_000;
	private static final long MIN = 60_000;

	@Test
	public void firstKillOnlyStartsTheClock()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		assertEquals(0, t.getCountedKills());
		assertEquals(0, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void steadyKillEvery30sIs120PerHour()
	{
		KillRateTracker t = new KillRateTracker();
		for (int i = 0; i <= 10; i++)
		{
			t.recordKills(1, i * 30_000L, PAUSE_MS);
		}
		assertEquals(10, t.getCountedKills());
		assertEquals(120, t.getKillsPerHour(), 0.001);
		assertEquals(300_000, t.getKillingMs());
	}

	@Test
	public void gapEqualToThePauseTimeStillCounts()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, PAUSE_MS, PAUSE_MS);
		assertEquals(1, t.getCountedKills());
		assertEquals(0, t.getBreakMs());
	}

	@Test
	public void pausesAreLeftOutOfTheRate()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 30_000, PAUSE_MS);
		t.recordKills(1, 60_000, PAUSE_MS);
		// 10 minute bank trip: neither the gap nor the kill that ended it counts
		t.recordKills(1, 660_000, PAUSE_MS);
		t.recordKills(1, 690_000, PAUSE_MS);
		assertEquals(3, t.getCountedKills());
		assertEquals(120, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void aPauseUnderFifteenMinutesIsRememberedAsABreak()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 30_000, PAUSE_MS);
		t.recordKills(1, 30_000 + 5 * MIN, PAUSE_MS);
		assertEquals(5 * MIN, t.getBreakMs());
		assertEquals(30_000, t.getKillingMs());
	}

	@Test
	public void aPauseOverFifteenMinutesIsNotABreak()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 15 * MIN, PAUSE_MS);
		assertEquals(15 * MIN, t.getBreakMs());

		t.recordKills(1, 15 * MIN + 15 * MIN + 1, PAUSE_MS);
		assertEquals(15 * MIN, t.getBreakMs());
		assertEquals(0, t.getCountedKills());
	}

	@Test
	public void multiKillTickCountsEveryKill()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(3, 60_000, PAUSE_MS);
		assertEquals(3, t.getCountedKills());
		assertEquals(180, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void restartClockLeavesASuperiorFightOutOfBothRateAndBreaks()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 30_000, PAUSE_MS);
		// superior kill 5 minutes later: clock restarts, nothing counted, no break
		t.restartClock(30_000 + 5 * MIN);
		t.recordKills(1, 60_000 + 5 * MIN, PAUSE_MS);
		assertEquals(2, t.getCountedKills());
		assertEquals(120, t.getKillsPerHour(), 0.001);
		assertEquals(0, t.getBreakMs());
	}

	@Test
	public void clearClockMeansTimeLoggedOutIsNotABreak()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 30_000, PAUSE_MS);
		t.clearClock();
		// back 10 minutes later: this kill only starts the clock again
		t.recordKills(1, 30_000 + 10 * MIN, PAUSE_MS);
		assertEquals(0, t.getBreakMs());
		assertEquals(1, t.getCountedKills());
		t.recordKills(1, 60_000 + 10 * MIN, PAUSE_MS);
		assertEquals(2, t.getCountedKills());
		assertEquals(120, t.getKillsPerHour(), 0.001);
	}

	@Test
	public void rollingAverageFollowsRecentPace()
	{
		KillRateTracker t = new KillRateTracker();
		long now = 0;
		t.recordKills(1, now, PAUSE_MS);
		// 60 kills at 36s each (100/hr)
		for (int i = 0; i < 60; i++)
		{
			now += 36_000;
			t.recordKills(1, now, PAUSE_MS);
		}
		// 25 kills at 24s each (150/hr)
		for (int i = 0; i < 25; i++)
		{
			now += 24_000;
			t.recordKills(1, now, PAUSE_MS);
		}
		assertEquals(150, t.getKillsPerHour(25), 0.001);
		// whole-task average is still dragged down by the slower kills
		assertEquals(85 * 3_600_000d / (60 * 36_000 + 25 * 24_000), t.getKillsPerHour(), 0.001);
	}

	@Test
	public void rollingWithFewerKillsUsesWhatThereIs()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 30_000, PAUSE_MS);
		assertEquals(120, t.getKillsPerHour(25), 0.001);
	}

	@Test
	public void noBreakEstimateUntilTenMinutesOfKillingWhenNothingIsSaved()
	{
		KillRateTracker t = new KillRateTracker();
		long now = 0;
		t.recordKills(1, now, PAUSE_MS);
		// 5 minutes of killing, then a 3 minute break
		for (int i = 0; i < 10; i++)
		{
			now += 30_000;
			t.recordKills(1, now, PAUSE_MS);
		}
		now += 3 * MIN;
		t.recordKills(1, now, PAUSE_MS);
		assertEquals(3 * MIN, t.getBreakMs());
		assertEquals(-1, t.getBreakRatio(-1), 0.0001);

		// 5 more minutes of killing reaches the 10 minute mark: 3 min of breaks per 10 min of killing
		t.recordKills(1, now + 30_000, PAUSE_MS);
		now += 30_000;
		for (int i = 0; i < 9; i++)
		{
			now += 30_000;
			t.recordKills(1, now, PAUSE_MS);
		}
		assertEquals(10 * MIN, t.getKillingMs());
		assertEquals(0.3, t.getBreakRatio(-1), 0.0001);
	}

	@Test
	public void aSavedEstimateIsUsedFromTheFirstKill()
	{
		KillRateTracker t = new KillRateTracker();
		assertEquals(0.2, t.getBreakRatio(0.2), 0.0001);
		assertEquals(0.0, t.getBreakRatio(0.0), 0.0001);
	}

	@Test
	public void aSavedEstimateCountsAsThirtyMinutesOfKilling()
	{
		// saved: 0.2 (6 minutes of breaks per 30 of killing). This session: 5 minutes of breaks in 10 of killing.
		double blended = KillRateTracker.breakRatio(0.2, 10 * MIN, 5 * MIN);
		assertEquals((6.0 + 5.0) / 40.0, blended, 0.0001);
	}

	@Test
	public void aLongSessionGraduallyTakesOverFromTheSavedEstimate()
	{
		double early = KillRateTracker.breakRatio(0.5, 10 * MIN, 0);
		double late = KillRateTracker.breakRatio(0.5, 300 * MIN, 0);
		// both pulled towards the session's 0, the longer session far more
		assertEquals(0.5 * 30 / 40, early, 0.0001);
		assertEquals(0.5 * 30 / 330, late, 0.0001);
	}

	@Test
	public void resetForgetsEverything()
	{
		KillRateTracker t = new KillRateTracker();
		t.recordKills(1, 0, PAUSE_MS);
		t.recordKills(1, 30_000, PAUSE_MS);
		t.recordKills(1, 30_000 + 5 * MIN, PAUSE_MS);
		t.reset();
		assertEquals(0, t.getCountedKills());
		assertEquals(0, t.getKillingMs());
		assertEquals(0, t.getBreakMs());
		assertEquals(0, t.getKillsPerHour(), 0.001);
		// and the next kill only starts the clock again
		t.recordKills(1, 10 * MIN, PAUSE_MS);
		assertEquals(0, t.getCountedKills());
	}
}

